// Logo ditanam di sini. Kalau mau pakai URL sendiri (CodePen Assets), ganti isi LOGO dengan URL gambarnya.
const LOGO = "data:image/webp;base64,";
document.querySelectorAll(".logo-img").forEach(function(i){ i.src = LOGO; });

// ===== Link presentasi Canva =====
// Isi dengan link embed dari Canva (Bagikan > Lihat selengkapnya > Sematkan).
// Link yang berakhiran /view atau /watch otomatis ditambah ?embed.
const CANVA_HOME   = "https://canva.link/u1ls2i5mym3eosp";
const CANVA_DESIGN = "https://canva.link/u1ls2i5mym3eosp"; // ganti kalau PPT Design punya link sendiri
function canvaEmbedUrl(u){
  if(/canva\.com\/design\/.+\/(view|watch)/.test(u) && u.indexOf("embed")<0){
    return u + (u.indexOf("?")<0 ? "?embed" : "&embed");
  }
  return u;
}
document.querySelectorAll("[data-canva]").forEach(function(box){
  var u = box.getAttribute("data-canva")==="design" ? CANVA_DESIGN : CANVA_HOME;
  box.querySelector("iframe").src = canvaEmbedUrl(u);
  box.parentNode.querySelectorAll(".canva-open").forEach(function(a){ a.href = u; });
});

(function(){
  /* ---------- router ---------- */
  var views=['home','design','product'];
  var titles={home:'Ring the Bell | Ring the Bell Group',design:'Desain | Ring the Bell',product:'Game | Ring the Bell'};
  function route(){
    var h=(location.hash||'#home').slice(1);
    if(views.indexOf(h)<0)h='home';
    views.forEach(function(v){document.getElementById(v).hidden=(v!==h)});
    document.querySelectorAll('nav a').forEach(function(a){
      if(a.dataset.nav===h)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');
    });
    document.title=titles[h];
    window.scrollTo(0,0);
    if(h==='product')fit();
    else if(state.mode==='play'){endGame(true)}
  }
  window.addEventListener('hashchange',route);

  /* ---------- game setup ---------- */
  var cv=document.getElementById('game'),ctx=cv.getContext('2d');
  var S=520,C=S/2,R=185,BAND=30,scale=1;
  var reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var els={score:document.getElementById('score'),best:document.getElementById('best'),combo:document.getElementById('combo'),
    lives:document.getElementById('lives'),msg:document.getElementById('msg'),overlay:document.getElementById('overlay'),
    ovTitle:document.getElementById('ov-title'),ovText:document.getElementById('ov-text'),start:document.getElementById('startBtn'),
    mute:document.getElementById('muteBtn')};
  var FEATHER='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 3C10 3 5 9 5 15c0 1.6.4 3 1 4L3 22l1.2.6L8 19.5c1 .3 2 .5 3 .5 6 0 9-6 9-17z"/></svg>';

  var state={mode:'idle',score:0,best:0,combo:0,lives:3,hits:0,marker:0,dir:1,speed:70,
    zoneC:300,zoneW:64,travelled:0,ring:-1,swing:0,shock:-1,flash:0,flashColor:'',sparks:[],muted:false};
  try{state.best=parseInt(localStorage.getItem('rtb_best')||'0',10)||0}catch(e){}

  function fit(){
    var w=cv.clientWidth||520,dpr=window.devicePixelRatio||1;
    cv.width=Math.round(w*dpr);cv.height=Math.round(w*dpr);
    scale=cv.width/S;
  }
  if(window.ResizeObserver)new ResizeObserver(fit).observe(cv);
  window.addEventListener('resize',fit);

  /* ---------- audio ---------- */
  var ac=null;
  var NOTES=[392,440,523.25,587.33,659.25];
  function audio(){
    if(!ac){try{ac=new (window.AudioContext||window.webkitAudioContext)()}catch(e){ac=null}}
    if(ac&&ac.state==='suspended')ac.resume();
    return ac;
  }
  function chime(freq,vol){
    if(state.muted||!audio())return;
    var t=ac.currentTime,parts=[1,2.01,2.76,5.4,8.93];
    parts.forEach(function(m,i){
      var o=ac.createOscillator(),g=ac.createGain();
      o.type='sine';o.frequency.value=freq*m;
      g.gain.setValueAtTime(vol/(i+1.3),t);
      g.gain.exponentialRampToValueAtTime(0.0001,t+2.4/(i*0.7+1));
      o.connect(g);g.connect(ac.destination);o.start(t);o.stop(t+2.5);
    });
  }
  function thud(){
    if(state.muted||!audio())return;
    var t=ac.currentTime,o=ac.createOscillator(),g=ac.createGain();
    o.type='triangle';o.frequency.setValueAtTime(150,t);o.frequency.exponentialRampToValueAtTime(55,t+.3);
    g.gain.setValueAtTime(.3,t);g.gain.exponentialRampToValueAtTime(0.0001,t+.35);
    o.connect(g);g.connect(ac.destination);o.start(t);o.stop(t+.4);
  }

  /* ---------- helpers ---------- */
  function angDiff(a,b){var d=((a-b)%360+540)%360-180;return d}
  function pos(a,r){var rad=a*Math.PI/180;return {x:C+r*Math.sin(rad),y:C-r*Math.cos(rad)}}
  function canvasAngle(a){return (a-90)*Math.PI/180}
  function setMsg(t){els.msg.textContent=t}
  function renderLives(){
    var h='';for(var i=0;i<3;i++)h+=FEATHER.replace('<svg','<svg class="'+(i<state.lives?'':'lost')+'"');
    els.lives.innerHTML=h;
  }
  function renderHud(){
    els.score.textContent=state.score;els.best.textContent=state.best;els.combo.textContent=state.combo;renderLives();
  }

  /* ---------- game flow ---------- */
  function newZone(){
    state.zoneC=((state.marker+state.dir*(90+Math.random()*180))%360+360)%360;
    state.travelled=0;
  }
  function startGame(){
    audio();
    state.mode='play';state.score=0;state.combo=0;state.lives=3;state.hits=0;
    state.dir=1;state.speed=110;state.zoneW=70;state.ring=-1;state.shock=-1;state.sparks=[];
    newZone();
    els.overlay.hidden=true;
    setMsg('Tunggu cahaya emas...');
    renderHud();
  }
  function endGame(silent){
    state.mode='over';
    if(state.score>state.best){state.best=state.score;try{localStorage.setItem('rtb_best',String(state.best))}catch(e){}}
    renderHud();
    if(silent){state.mode='idle';els.ovTitle.textContent='Siap membunyikan lonceng?';
      els.ovText.textContent='Ketuk layar atau tekan Spasi saat anak panah berada di cahaya emas.';
      els.start.textContent='Mulai bermain';els.overlay.hidden=false;return}
    els.ovTitle.textContent='Lonceng terdiam';
    els.ovText.textContent='Skor akhir '+state.score+' dengan '+state.hits+' bunyi berhasil.'+(state.score>0&&state.score>=state.best?' Ini rekor barumu!':'');
    els.start.textContent='Main lagi';
    els.overlay.hidden=false;
    setMsg('');
  }
  function spark(x,y){
    if(reduceMotion)return;
    for(var i=0;i<22;i++){
      var a=Math.random()*Math.PI*2,v=60+Math.random()*160;
      state.sparks.push({x:x,y:y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:1});
    }
  }
  function miss(reason){
    state.lives--;state.combo=0;state.travelled=0;
    state.ring=0;state.swing=.09;state.flash=1;state.flashColor='200,40,50';
    thud();
    setMsg(reason==='timeout'?'Terlalu lama menunggu!':'Meleset!');
    renderHud();
    if(state.lives<=0)endGame(false);
  }
  function press(){
    if(state.mode!=='play')return;
    var d=Math.abs(angDiff(state.marker,state.zoneC));
    if(d<=state.zoneW/2){
      var perfect=d<=state.zoneW*0.17;
      state.hits++;state.combo++;
      var mult=1+Math.floor((state.combo-1)/4);
      state.score+=(perfect?20:10)*mult;
      var p=pos(state.marker,R);spark(p.x,p.y);
      state.ring=0;state.swing=perfect?.42:.3;state.shock=0;state.flash=1;state.flashColor='255,200,61';
      var f=NOTES[(state.hits-1)%NOTES.length];
      chime(f,perfect?.3:.2);if(perfect)chime(f*2,.12);
      setMsg(perfect?'Sempurna! x'+mult:'Bagus! x'+mult);
      state.zoneW=Math.max(20,state.zoneW-3);
      state.speed=Math.min(340,state.speed+8);
      if(state.hits%4===0)state.dir*=-1;
      newZone();
      if(state.score>state.best){state.best=state.score}
      renderHud();
    }else{
      miss('miss');
    }
  }

  /* ---------- input ---------- */
  cv.addEventListener('pointerdown',function(e){e.preventDefault();press()});
  els.start.addEventListener('click',startGame);
  els.mute.addEventListener('click',function(){
    state.muted=!state.muted;
    els.mute.textContent='Efek: '+(state.muted?'mati':'nyala');
    els.mute.setAttribute('aria-pressed',String(state.muted));
  });
  document.addEventListener('keydown',function(e){
    if(location.hash!=='#product')return;
    if(e.code==='Space'||e.key===' '){
      if(e.target&&e.target.tagName==='BUTTON')return;
      e.preventDefault();
      if(state.mode==='play')press();else startGame();
    }
  });

  /* ---------- drawing ---------- */
  function star4(x,y,r,fill,stroke,lw){
    ctx.beginPath();
    for(var i=0;i<8;i++){
      var a=i*Math.PI/4,rr=(i%2===0)?r:r*.24;
      var px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr;
      if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);
    }
    ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill()}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw||1;ctx.stroke()}
  }
  function arc(a0,a1,r,w,color){
    ctx.beginPath();ctx.arc(C,C,r,canvasAngle(a0),canvasAngle(a1));
    ctx.lineWidth=w;ctx.strokeStyle=color;ctx.lineCap='butt';ctx.stroke();
  }
  function drawBell(swingRad){
    ctx.save();
    ctx.translate(C,C-70);
    ctx.scale(1.15,1.15);
    ctx.rotate(swingRad);
    var g=ctx.createLinearGradient(-58,0,58,0);
    g.addColorStop(0,'#8a5a1c');g.addColorStop(.35,'#f6d98a');g.addColorStop(.7,'#d9a441');g.addColorStop(1,'#8a5a1c');
    // hanger
    ctx.strokeStyle='#ffc83d';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,9,8,0,Math.PI*2);ctx.stroke();
    // body
    ctx.beginPath();
    ctx.moveTo(-16,20);
    ctx.bezierCurveTo(-36,30,-40,72,-52,100);
    ctx.lineTo(-60,112);
    ctx.quadraticCurveTo(0,126,60,112);
    ctx.lineTo(52,100);
    ctx.bezierCurveTo(40,72,36,30,16,20);
    ctx.closePath();
    ctx.fillStyle=g;ctx.fill();
    ctx.lineWidth=2;ctx.strokeStyle='#5a3a10';ctx.stroke();
    // lip band
    ctx.beginPath();ctx.moveTo(-54,103);ctx.quadraticCurveTo(0,116,54,103);
    ctx.lineWidth=3;ctx.strokeStyle='rgba(90,58,16,.8)';ctx.stroke();
    // small star emblem
    star4(0,66,13,'rgba(107,15,31,.85)');
    // clapper
    ctx.beginPath();ctx.arc(-swingRad*14,122,9,0,Math.PI*2);
    ctx.fillStyle='#c99634';ctx.fill();ctx.strokeStyle='#5a3a10';ctx.lineWidth=2;ctx.stroke();
    ctx.restore();
  }

  var last=performance.now();
  function frame(now){
    var dt=Math.min(.05,(now-last)/1000);last=now;
    // update
    if(state.mode==='play'){
      var step=state.dir*state.speed*dt;
      state.marker=((state.marker+step)%360+360)%360;
      state.travelled+=Math.abs(step);
      if(state.travelled>720)miss('timeout');
    }else{
      state.marker=(state.marker+45*dt)%360;
    }
    if(state.ring>=0){state.ring+=dt;if(state.ring>2.6)state.ring=-1}
    if(state.shock>=0){state.shock+=dt;if(state.shock>.7)state.shock=-1}
    if(state.flash>0)state.flash=Math.max(0,state.flash-dt*2.2);
    for(var i=state.sparks.length-1;i>=0;i--){
      var s=state.sparks[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy+=120*dt;s.life-=dt*1.6;
      if(s.life<=0)state.sparks.splice(i,1);
    }

    // draw
    if(cv.width>0){
      ctx.setTransform(scale,0,0,scale,0,0);
      ctx.clearRect(0,0,S,S);

      // inner disc
      var disc=ctx.createRadialGradient(C,C,10,C,C,R);
      disc.addColorStop(0,'#8a1230');disc.addColorStop(1,'#2b0613');
      ctx.beginPath();ctx.arc(C,C,R-BAND/2,0,Math.PI*2);ctx.fillStyle=disc;ctx.fill();

      // flash glow
      if(state.flash>0){
        ctx.beginPath();ctx.arc(C,C,R-BAND/2,0,Math.PI*2);
        ctx.fillStyle='rgba('+state.flashColor+','+(state.flash*.22)+')';ctx.fill();
      }
      // shock wave
      if(state.shock>=0){
        var k=state.shock/.7;
        ctx.beginPath();ctx.arc(C,C,40+k*(R-60),0,Math.PI*2);
        ctx.lineWidth=3;ctx.strokeStyle='rgba(255,200,61,'+(1-k)*.7+')';ctx.stroke();
      }

      // ring band
      arc(0,359.99,R,BAND,'#17804a');
      arc(0,359.99,R+BAND/2,2.5,'#ffc83d');
      arc(0,359.99,R-BAND/2,2.5,'#ffc83d');

      // zone
      var z0=state.zoneC-state.zoneW/2,z1=state.zoneC+state.zoneW/2;
      arc(z0,z1,R,BAND,'#ffc83d');
      arc(state.zoneC-state.zoneW*.17,state.zoneC+state.zoneW*.17,R,BAND,'#fff1d0');

      // compass stars
      [0,90,180,270].forEach(function(a){var p=pos(a,R+BAND/2+30);star4(p.x,p.y,15,'#ffc83d')});

      // bell
      var sw=0;
      if(state.ring>=0)sw=state.swing*Math.sin(state.ring*16)*Math.exp(-state.ring*2.2);
      else if(state.mode!=='play')sw=Math.sin(now/900)*.05;
      drawBell(sw);

      // marker
      var mp=pos(state.marker,R);
      ctx.save();
      ctx.shadowColor='rgba(255,230,160,.9)';ctx.shadowBlur=16;
      star4(mp.x,mp.y,21,'#fff6dc','#b3122b',2);
      ctx.restore();

      // sparks
      state.sparks.forEach(function(s){
        ctx.globalAlpha=Math.max(0,s.life);
        ctx.fillStyle='#ffd978';ctx.beginPath();ctx.arc(s.x,s.y,3,0,Math.PI*2);ctx.fill();
      });
      ctx.globalAlpha=1;
    }
    requestAnimationFrame(frame);
  }

  /* ---------- musik petualangan (dibuat dengan Web Audio) ---------- */
  var music={on:false,master:null,bus:null,noise:null,timer:null,next:0,step:0};
  var BPM=132,EIGHTH=60/BPM/2;
  var ROOTS=[38,34,41,36,38,34,36,33];
  var PADS=[[50,53,57,62],[46,50,53,58],[53,57,60,65],[48,52,55,60],[50,53,57,62],[46,50,53,58],[48,52,55,60],[45,49,52,57]];
  var MEL=[
    [[0,74,2],[2,77,2],[4,81,3],[7,79,1]],
    [[0,82,2],[2,81,2],[4,79,2],[6,77,2]],
    [[0,77,2],[2,81,2],[4,84,3],[7,82,1]],
    [[0,81,4],[4,79,2],[6,76,2]],
    [[0,74,2],[2,77,2],[4,81,2],[6,86,2]],
    [[0,86,3],[3,84,1],[4,82,2],[6,81,2]],
    [[0,79,2],[2,84,2],[4,82,2],[6,79,2]],
    [[0,81,3],[3,79,1],[4,76,2],[6,73,2]]
  ];
  var ARP=[0,1,2,3,2,1,3,2];
  function mtof(m){return 440*Math.pow(2,(m-69)/12)}

  function buildMusic(){
    if(music.master)return true;
    if(!audio())return false;
    var a=ac;
    music.master=a.createGain();music.master.gain.value=0;
    var comp=a.createDynamicsCompressor();comp.threshold.value=-20;comp.ratio.value=4;
    music.bus=a.createGain();
    var conv=a.createConvolver(),len=Math.floor(a.sampleRate*2.2),buf=a.createBuffer(2,len,a.sampleRate);
    for(var c=0;c<2;c++){var d=buf.getChannelData(c);for(var i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,2.4)}
    conv.buffer=buf;
    var wet=a.createGain();wet.gain.value=.3;
    music.bus.connect(music.master);music.bus.connect(conv);conv.connect(wet);wet.connect(music.master);
    music.master.connect(comp);comp.connect(a.destination);
    var nb=a.createBuffer(1,a.sampleRate,a.sampleRate),nd=nb.getChannelData(0);
    for(var j=0;j<nd.length;j++)nd[j]=Math.random()*2-1;
    music.noise=nb;
    return true;
  }
  function tone(type,freq,t,dur,vol,o){
    o=o||{};
    var osc=ac.createOscillator(),g=ac.createGain(),f=ac.createBiquadFilter();
    osc.type=type;osc.frequency.value=freq;if(o.detune)osc.detune.value=o.detune;
    f.type='lowpass';f.frequency.value=o.lp||2000;
    var at=o.a||.01,rl=o.r||.1;
    g.gain.setValueAtTime(0.0001,t);
    g.gain.linearRampToValueAtTime(vol,t+at);
    g.gain.setValueAtTime(vol,t+Math.max(at,dur-rl));
    g.gain.exponentialRampToValueAtTime(0.0001,t+dur+rl);
    osc.connect(f);f.connect(g);g.connect(music.bus);
    osc.start(t);osc.stop(t+dur+rl+.05);
  }
  function noiseHit(t,dur,vol,type,freq){
    var s=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();
    s.buffer=music.noise;f.type=type;f.frequency.value=freq;
    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    s.connect(f);f.connect(g);g.connect(music.bus);s.start(t);s.stop(t+dur+.02);
  }
  function drum(t,f0,f1,dur,vol){
    var o=ac.createOscillator(),g=ac.createGain();
    o.type='sine';o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(f1,t+dur);
    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    o.connect(g);g.connect(music.bus);o.start(t);o.stop(t+dur+.02);
  }
  function scheduleStep(step,t){
    var bar=Math.floor(step/8)%8,s=step%8,ch=PADS[bar];
    if(s===0){
      ch.forEach(function(m,i){tone('sawtooth',mtof(m),t,EIGHTH*8,.03,{a:.4,r:.6,lp:1100,detune:(i%2?7:-7)})});
    }
    tone('sawtooth',mtof(ROOTS[bar]+(s%4===3?12:0)),t,EIGHTH*.9,.1,{a:.01,r:.08,lp:520});
    tone('triangle',mtof(ch[ARP[s]]+12),t,EIGHTH*.7,.045,{a:.005,r:.15,lp:3500});
    MEL[bar].forEach(function(n){
      if(n[0]!==s)return;
      var d=EIGHTH*n[2]*.95;
      tone('sawtooth',mtof(n[1]),t,d,.06,{a:.04,r:.14,lp:2400});
      tone('square',mtof(n[1]),t,d,.02,{a:.04,r:.14,lp:1700,detune:8});
    });
    if(s===0||s===4)drum(t,150,45,.28,.6);
    if(s===3||s===7)drum(t,115,60,.2,.3);
    if(s===2||s===6){noiseHit(t,.2,.22,'bandpass',1800);drum(t,230,120,.12,.14)}
    noiseHit(t,.04,s%2?.04:.07,'highpass',7000);
    if(s===0&&bar%4===0)noiseHit(t,1.4,.1,'highpass',5000);
  }
  function pump(){
    while(music.next<ac.currentTime+.25){
      scheduleStep(music.step,music.next);
      music.next+=EIGHTH;music.step++;
    }
  }
  function renderMusicBtns(){
    document.querySelectorAll('[data-music]').forEach(function(b){
      var lab=b.querySelector('.music-label');
      if(lab)lab.textContent='Musik: '+(music.on?'nyala':'mati');
      else if(b.hasAttribute('data-hero-music'))b.textContent=music.on?'Hentikan musik':'Putar musik petualangan';
      else b.textContent='Musik: '+(music.on?'nyala':'mati');
      b.setAttribute('aria-pressed',String(music.on));
      b.classList.toggle('on',music.on&&b.classList.contains('music-btn'));
    });
  }
  function startMusic(){
    if(!buildMusic())return;
    music.on=true;
    var t=ac.currentTime;
    music.master.gain.cancelScheduledValues(t);
    music.master.gain.setValueAtTime(music.master.gain.value,t);
    music.master.gain.linearRampToValueAtTime(.5,t+1.2);
    music.next=t+.08;music.step=0;
    clearInterval(music.timer);music.timer=setInterval(pump,50);
    pump();renderMusicBtns();
  }
  function stopMusic(){
    music.on=false;
    var t=ac.currentTime;
    music.master.gain.cancelScheduledValues(t);
    music.master.gain.setValueAtTime(music.master.gain.value,t);
    music.master.gain.linearRampToValueAtTime(0,t+.6);
    setTimeout(function(){if(!music.on)clearInterval(music.timer)},700);
    renderMusicBtns();
  }
  document.querySelectorAll('[data-music]').forEach(function(b){
    b.addEventListener('click',function(){if(music.on)stopMusic();else startMusic()});
  });
  document.addEventListener('visibilitychange',function(){
    if(!ac||!music.on)return;
    if(document.hidden)ac.suspend();else ac.resume();
  });


  renderHud();
  route();
  requestAnimationFrame(frame);
})();

/* ---------- efek: bara api melayang + muncul saat scroll ---------- */
(function(){
  document.documentElement.classList.add('js');
  var els=document.querySelectorAll('.reveal');
  if(!('IntersectionObserver' in window)){els.forEach(function(e){e.classList.add('in')})}
  else{
    var io=new IntersectionObserver(function(es){
      es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}});
    },{threshold:.12});
    els.forEach(function(e){io.observe(e)});
  }

  var cv=document.getElementById('embers');
  if(!cv)return;
  var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(reduce){cv.style.display='none';return}
  var ctx=cv.getContext('2d'),dpr=Math.min(window.devicePixelRatio||1,1.5),W=0,H=0,ps=[];
  function size(){W=window.innerWidth;H=window.innerHeight;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
  function mk(init){
    return {x:Math.random()*W,y:init?Math.random()*H:H+10,r:1+Math.random()*2.6,vy:18+Math.random()*40,
      sw:Math.random()*6.28,sa:10+Math.random()*25,c:Math.random()<.6?'255,200,61':'255,106,31',a:.35+Math.random()*.55};
  }
  size();
  var n=window.innerWidth<600?28:50;
  for(var i=0;i<n;i++)ps.push(mk(true));
  window.addEventListener('resize',size);
  var last=performance.now();
  function loop(now){
    var dt=Math.min(.05,(now-last)/1000);last=now;
    if(!document.hidden){
      ctx.clearRect(0,0,W,H);
      for(var i=0;i<ps.length;i++){
        var p=ps[i];
        p.y-=p.vy*dt;p.sw+=dt;
        if(p.y<-12){ps[i]=mk(false);continue}
        var x=p.x+Math.sin(p.sw)*p.sa,al=p.a*Math.min(1,p.y/(H*.55));
        ctx.fillStyle='rgba('+p.c+','+(al*.18)+')';ctx.beginPath();ctx.arc(x,p.y,p.r*3.2,0,6.283);ctx.fill();
        ctx.fillStyle='rgba('+p.c+','+al+')';ctx.beginPath();ctx.arc(x,p.y,p.r,0,6.283);ctx.fill();
      }
    }
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
